#include "platform.h"
#include "build_config.h"
#include "trust_store.h"
#include <bcrypt.h>
#include <fstream>
#include <memory>
namespace pet {
std::wstring wide(const std::string&s){if(s.empty())return {};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),nullptr,0);if(!n)throw std::runtime_error("UTF-8");std::wstring w(n,0);MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),int(s.size()),w.data(),n);return w;}
std::string utf8(const std::wstring&s){if(s.empty())return {};int n=WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),int(s.size()),nullptr,0,nullptr,nullptr);if(!n)throw std::runtime_error("UTF-16");std::string r(n,0);WideCharToMultiByte(CP_UTF8,WC_ERR_INVALID_CHARS,s.data(),int(s.size()),r.data(),n,nullptr,nullptr);return r;}
fs::path executable(){std::wstring w(32768,0);DWORD n=GetModuleFileNameW(nullptr,w.data(),DWORD(w.size()));if(!n||n>=w.size())throw std::runtime_error("Executable path");w.resize(n);return fs::path(w);}
fs::path appData(){PWSTR p=nullptr;if(FAILED(SHGetKnownFolderPath(FOLDERID_LocalAppData,0,nullptr,&p)))throw std::runtime_error("LocalAppData unavailable");fs::path r=fs::path(p)/L"DesktopPet";CoTaskMemFree(p);fs::create_directories(r);return r;}
std::string randomId(){unsigned char b[16];if(BCryptGenRandom(nullptr,b,16,BCRYPT_USE_SYSTEM_PREFERRED_RNG)<0)throw std::runtime_error("RNG");const char*h="0123456789abcdef";std::string s;for(auto c:b){s+=h[c>>4];s+=h[c&15];}return s;}
void rejectReparse(const fs::path&p){auto q=fs::absolute(p);for(auto i=q;i!=i.root_path()&&!i.empty();i=i.parent_path()){auto a=GetFileAttributesW(i.c_str());if(a!=INVALID_FILE_ATTRIBUTES&&(a&FILE_ATTRIBUTE_REPARSE_POINT))throw std::runtime_error("Reparse path rejected");}}
fs::path settingsPath(){auto dir=executable().parent_path();auto probe=dir/(L".write-"+wide(randomId()));HANDLE h=CreateFileW(probe.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_TEMPORARY|FILE_FLAG_DELETE_ON_CLOSE,nullptr);if(h!=INVALID_HANDLE_VALUE){CloseHandle(h);return dir/L"config.json";}return appData()/L"config.json";}
std::vector<unsigned char> readBytes(const fs::path&p,size_t limit){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("Cannot open file");auto size=f.tellg();if(size<0||static_cast<uint64_t>(size)>limit)throw std::runtime_error("File exceeds limit");std::vector<unsigned char> b(static_cast<size_t>(size));f.seekg(0);if(!b.empty()&&!f.read(reinterpret_cast<char*>(b.data()),std::streamsize(b.size())))throw std::runtime_error("Cannot read file");return b;}
std::string readText(const fs::path&p,size_t limit){auto b=readBytes(p,limit);return std::string(b.begin(),b.end());}
void atomicWrite(const fs::path&p,const void*data,size_t size){fs::create_directories(p.parent_path());auto temp=p;temp+=L".tmp-"+wide(randomId());HANDLE h=CreateFileW(temp.c_str(),GENERIC_WRITE,0,nullptr,CREATE_NEW,FILE_ATTRIBUTE_NORMAL,nullptr);if(h==INVALID_HANDLE_VALUE)throw std::runtime_error("Cannot write file");DWORD done=0;bool ok=size<=MAXDWORD&&WriteFile(h,data,DWORD(size),&done,nullptr)&&done==size&&FlushFileBuffers(h);CloseHandle(h);if(!ok||!MoveFileExW(temp.c_str(),p.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH)){DeleteFileW(temp.c_str());throw std::runtime_error("Atomic write failed");}}
void saveConfig(const fs::path&p,const Config&c){writeText(p,c.json().dump());}
std::wstring quote(const std::wstring&s){std::wstring r=L"\"";unsigned slash=0;for(auto c:s){if(c==L'\\'){++slash;continue;}if(c==L'"')r.append(slash*2+1,L'\\');else r.append(slash,L'\\');slash=0;r+=c;}r.append(slash*2,L'\\');return r+L'"';}
PROCESS_INFORMATION launch(const fs::path&exe,const std::vector<std::wstring>&args){std::wstring cmd=quote(exe.wstring());for(auto&a:args)cmd+=L" "+quote(a);STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};if(!CreateProcessW(exe.c_str(),cmd.data(),nullptr,nullptr,FALSE,0,nullptr,exe.parent_path().c_str(),&si,&pi))throw std::runtime_error("Cannot start process");return pi;}
void setStartup(bool enabled){HKEY key=nullptr;if(RegCreateKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,nullptr,0,KEY_SET_VALUE,nullptr,&key,nullptr)!=ERROR_SUCCESS)throw std::runtime_error("Cannot open startup setting");LSTATUS status;if(enabled){auto cmd=quote(executable().wstring());status=RegSetValueExW(key,L"DesktopPet",0,REG_SZ,reinterpret_cast<const BYTE*>(cmd.c_str()),DWORD((cmd.size()+1)*sizeof(wchar_t)));}else{status=RegDeleteValueW(key,L"DesktopPet");if(status==ERROR_FILE_NOT_FOUND)status=ERROR_SUCCESS;}RegCloseKey(key);if(status!=ERROR_SUCCESS)throw std::runtime_error("Cannot save startup setting");}
static std::vector<unsigned char> unhex(const std::string&s){if(s.size()%2)throw std::runtime_error("hex");std::vector<unsigned char> b;for(size_t i=0;i<s.size();i+=2){auto digit=[](char c)->int{if(c>='0'&&c<='9')return c-'0';if(c>='a'&&c<='f')return c-'a'+10;if(c>='A'&&c<='F')return c-'A'+10;throw std::runtime_error("hex");};b.push_back(static_cast<unsigned char>(digit(s[i])*16+digit(s[i+1])));}return b;}
static std::vector<unsigned char> hash(const std::vector<unsigned char>&data){BCRYPT_ALG_HANDLE alg=nullptr;BCRYPT_HASH_HANDLE h=nullptr;std::vector<unsigned char> result(32);if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("SHA256 provider");NTSTATUS s=BCryptCreateHash(alg,&h,nullptr,0,nullptr,0,0);if(s>=0)s=BCryptHashData(h,const_cast<PUCHAR>(data.data()),ULONG(data.size()),0);if(s>=0)s=BCryptFinishHash(h,result.data(),32,0);if(h)BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(alg,0);if(s<0)throw std::runtime_error("SHA256 failed");return result;}
std::string sha256(const std::vector<unsigned char>&data){auto b=hash(data);const char*h="0123456789abcdef";std::string s;for(auto c:b){s+=h[c>>4];s+=h[c&15];}return s;}
bool publicKeyValid(const std::string&point){
 if(point.size()!=128)return false;std::vector<unsigned char> key;try{key=unhex(point);}catch(...){return false;}
 BCRYPT_ECCKEY_BLOB header{BCRYPT_ECDSA_PUBLIC_P256_MAGIC,32};std::vector<unsigned char>blob(sizeof(header)+key.size());memcpy(blob.data(),&header,sizeof(header));memcpy(blob.data()+sizeof(header),key.data(),key.size());BCRYPT_ALG_HANDLE alg=nullptr;BCRYPT_KEY_HANDLE handle=nullptr;if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_ECDSA_P256_ALGORITHM,nullptr,0)<0)return false;auto status=BCryptImportKeyPair(alg,nullptr,BCRYPT_ECCPUBLIC_BLOB,&handle,blob.data(),ULONG(blob.size()),0);if(handle)BCryptDestroyKey(handle);BCryptCloseAlgorithmProvider(alg,0);return status>=0;
}
bool verifySignature(const std::vector<unsigned char>&message,const std::vector<unsigned char>&sig,const std::string&publicKey){if(publicKey.size()!=128||sig.size()!=64)return false;auto key=unhex(publicKey);BCRYPT_ECCKEY_BLOB header{BCRYPT_ECDSA_PUBLIC_P256_MAGIC,32};std::vector<unsigned char> blob(sizeof(header)+key.size());memcpy(blob.data(),&header,sizeof(header));memcpy(blob.data()+sizeof(header),key.data(),key.size());BCRYPT_ALG_HANDLE a=nullptr;BCRYPT_KEY_HANDLE k=nullptr;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_ECDSA_P256_ALGORITHM,nullptr,0)<0)return false;NTSTATUS s=BCryptImportKeyPair(a,nullptr,BCRYPT_ECCPUBLIC_BLOB,&k,blob.data(),ULONG(blob.size()),0);auto digest=hash(message);if(s>=0)s=BCryptVerifySignature(k,nullptr,digest.data(),ULONG(digest.size()),const_cast<PUCHAR>(sig.data()),ULONG(sig.size()),0);if(k)BCryptDestroyKey(k);BCryptCloseAlgorithmProvider(a,0);return s>=0;}
bool signatureOK(const std::vector<unsigned char>&message,const std::vector<unsigned char>&sig){return verifyTrustedManifest(message,sig);}
}
